# A shared workbench, not new workflow stages. Identity checks belong to the
# host; evidence interpretation and readiness belong to the research Agent.
BUILTINS.update({
    "record_finding": ("research", {**object_schema({
        "statement": STRING, "status": {**STRING, "enum": list(STATUSES)},
        "support": {**REFERENCES, "minItems": 1}, "conditions": STRINGS,
        "limits": STRINGS, "replaces": STRING, "reason": {"type": "string"},
    }), "required": ["statement", "status", "support"]}),
    "record_conflict": ("research", {**object_schema({
        "question": STRING, "findings": {**REFERENCES, "minItems": 1},
        "disposition": {**STRING, "enum": list(DISPOSITIONS)},
        "explanation": {"type": "string"}, "evidence": REFERENCES, "replaces": STRING,
    }), "required": ["question", "findings"]}),
    "prepare_writing": ("research", {**object_schema({
        "findings": REFERENCES,
        "coverage": {"type": "array", "minItems": 1, "items": {
            **object_schema({"question": {"type": "integer", "minimum": 0},
                             "findings": REFERENCES, "limitation": {"type": "string"}}),
            "required": ["question", "findings"],
        }},
        "rationale": STRING, "limitations": STRINGS, "replaces": STRING,
    }), "required": ["findings", "coverage", "rationale"]}),
    "read_draft": ("research", {**object_schema({
        "ref": STRING, "offset": {"type": "integer", "minimum": 0},
        "limit": {"type": "integer", "minimum": 1},
    }), "required": []}),
    "patch_draft": ("research", {**object_schema({
        "base": STRING, "basis": STRING, "evidence": REFERENCES,
        "edits": {"type": "array", "minItems": 1, "items": object_schema({
            "old": STRING, "new": {"type": "string"},
        })},
        "handoff": {"type": "string"},
    }), "required": ["base", "edits"]}),
})
BUILTINS["draft_report"][1]["properties"]["basis"] = STRING
BUILTINS["find_artifacts"][1]["properties"]["kind"]["enum"].extend(sorted(RESEARCH_KINDS))
BUILTINS["read_context"][1]["properties"]["section"]["enum"].extend([
    "research_questions", "research_findings", "research_conflicts",
])

receipts = self.store.matching(study, "draft_saved", {"ref": draft.ref})
return {"ref": draft.ref, "receipt": receipts[-1].ref if receipts else None,
        "basis": draft.body["basis"], "state": "saved_not_finished"}

if call.name in {"record_finding", "record_conflict", "prepare_writing"}:
    method = getattr(self.research, call.name)
    item = method(study, work.ref, epoch, _operation=identity(step, index, call.name), **args)
    return {"ref": item.ref, "kind": item.kind,
            "status": item.body.get("status", item.body.get("disposition")),
            "semantic_verification": "Agent judgment, not host certification"}
if call.name == "read_draft":
    return self.writing.read(study, work.ref, epoch, capacity=self.context_chars // 3, **args)
if call.name == "patch_draft":
    return self.writing.save(study, work.ref, epoch, step, index,
                             research_refs=self._handoff_inputs(study, work), **args)
